import { existsSync, readFileSync } from 'node:fs';
import { parseEnv } from 'node:util';
import { parseHttpOrigin } from '../src/lib/public-url.ts';
import { parseSupabasePublicConfig } from '../src/lib/supabase/config.ts';

function envFiles(mode) {
  return [
    '.env',
    `.env.${mode}`,
    ...(mode === 'test' ? [] : ['.env.local']),
    `.env.${mode}.local`,
  ];
}

export function loadPublicEnv(
  mode,
  baseEnv = process.env,
) {
  const values = {};

  for (const path of envFiles(mode)) {
    if (!existsSync(path)) continue;

    Object.assign(
      values,
      parseEnv(readFileSync(path, 'utf8')),
    );
  }

  for (const key of [
    'NEXT_PUBLIC_SITE_URL',
    'NEXT_PUBLIC_SUPABASE_URL',
    'NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY',
    'NEXT_PUBLIC_MAP_STYLE_URL',
    'NEXT_PUBLIC_MAP_CSP_ORIGINS',
  ]) {
    if (baseEnv[key] !== undefined) {
      values[key] = baseEnv[key];
    }
  }

  return values;
}

function validHttpUrl(value) {
  try {
    const url = new URL(value);
    return (
      (url.protocol === 'https:' ||
        url.protocol === 'http:') &&
      !url.username &&
      !url.password
    );
  } catch {
    return false;
  }
}

export function validatePublicEnv(
  values,
  { requirePublicConfig = false } = {},
) {
  const supabaseUrl =
    values.NEXT_PUBLIC_SUPABASE_URL?.trim();
  const supabaseKey =
    values.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY?.trim();

  if (
    requirePublicConfig &&
    !supabaseUrl &&
    !supabaseKey
  ) {
    return {
      ok: false,
      error: 'supabase_required',
    };
  }

  if (Boolean(supabaseUrl) !== Boolean(supabaseKey)) {
    return {
      ok: false,
      error: 'supabase_pair_incomplete',
    };
  }

  if (
    supabaseUrl &&
    !parseSupabasePublicConfig(
      supabaseUrl,
      supabaseKey,
    )
  ) {
    return {
      ok: false,
      error: 'supabase_url_invalid',
    };
  }

  const siteUrl = values.NEXT_PUBLIC_SITE_URL?.trim();

  if (requirePublicConfig && !siteUrl) {
    return {
      ok: false,
      error: 'site_url_required',
    };
  }

  if (siteUrl && !parseHttpOrigin(siteUrl)) {
    return {
      ok: false,
      error: 'site_url_invalid',
    };
  }

  const mapStyleUrl =
    values.NEXT_PUBLIC_MAP_STYLE_URL?.trim();

  if (mapStyleUrl && !validHttpUrl(mapStyleUrl)) {
    return {
      ok: false,
      error: 'map_style_url_invalid',
    };
  }

  const cspOrigins =
    values.NEXT_PUBLIC_MAP_CSP_ORIGINS?.trim();

  if (cspOrigins) {
    for (const item of cspOrigins.split(',')) {
      if (!parseHttpOrigin(item)) {
        return {
          ok: false,
          error: 'map_csp_origin_invalid',
        };
      }
    }
  }

  return {
    ok: true,
    supabaseConfigured: Boolean(supabaseUrl),
  };
}

import {
  loadPublicEnv,
  validatePublicEnv,
} from './public-env-contract.mjs';

const mode =
  process.argv[2] ||
  process.env.NODE_ENV ||
  'development';

const requirePublicConfig =
  process.argv.includes('--require-public-config') ||
  process.env.ACHEGUESE_REQUIRE_PUBLIC_ENV === '1' ||
  (mode === 'production' && process.env.VERCEL === '1');

const result = validatePublicEnv(
  loadPublicEnv(mode),
  { requirePublicConfig },
);

if (!result.ok) {
  const guidance =
    result.error === 'supabase_required'
      ? ' copie .env.example para .env.local e preencha NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY'
      : result.error === 'site_url_required'
        ? ' configure NEXT_PUBLIC_SITE_URL'
        : '';

  console.error(
    `[acheguese] public_env_invalid: ${result.error}.${guidance}`,
  );
  process.exitCode = 1;
} else {
  console.log(
    `[acheguese] public_env=PASS mode=${mode} required=${requirePublicConfig ? 'yes' : 'no'} supabase=${result.supabaseConfigured ? 'configured' : 'not-configured'}`,
  );
}

'use server';

import { revalidatePath } from 'next/cache';
import { notFound, redirect } from 'next/navigation';
import { hasClassifiedAdminRole } from '@/lib/auth/roles';
import { getSupabasePublicConfig } from '@/lib/supabase/config';
import { createSupabaseServerClient } from '@/lib/supabase/server';

async function requireClassifiedAdmin() {
  if (!getSupabasePublicConfig()) {
    redirect('/');
  }

  const supabase = await createSupabaseServerClient();
  const { data: claimsData } = await supabase.auth.getClaims();

  if (!hasClassifiedAdminRole(claimsData?.claims)) {
    notFound();
  }

  return supabase;
}

function readReason(formData: FormData) {
  const value = formData.get('reason');

  if (typeof value !== 'string') return null;

  const reason = value.trim();
  return reason.length >= 10 && reason.length <= 1000
    ? reason
    : null;
}

export async function approveClassifiedAction(classifiedId: string) {
  const supabase = await requireClassifiedAdmin();

  const { data, error } = await supabase
    .from('classifieds')
    .update({
      status: 'published',
      rejection_reason: null,
    })
    .eq('id', classifiedId)
    .eq('status', 'pending_review')
    .select('id')
    .maybeSingle();

  if (error || !data) {
    redirect('/admin/classificados?erro=aprovar');
  }

  revalidatePath('/admin/classificados');
  revalidatePath('/classificados');
  redirect('/admin/classificados?ok=aprovado');
}

export async function rejectClassifiedAction(
  classifiedId: string,
  formData: FormData,
) {
  const reason = readReason(formData);

  if (!reason) {
    redirect('/admin/classificados?erro=motivo');
  }

  const supabase = await requireClassifiedAdmin();

  const { data, error } = await supabase
    .from('classifieds')
    .update({
      status: 'rejected',
      rejection_reason: reason,
    })
    .eq('id', classifiedId)
    .eq('status', 'pending_review')
    .select('id')
    .maybeSingle();

  if (error || !data) {
    redirect('/admin/classificados?erro=rejeitar');
  }

  revalidatePath('/admin/classificados');
  revalidatePath('/classificados/meus');
  redirect('/admin/classificados?ok=rejeitado');
}

export async function pausePublishedClassifiedAction(
  classifiedId: string,
  formData: FormData,
) {
  const reason = readReason(formData);

  if (!reason) {
    redirect('/admin/classificados?erro=motivo');
  }

  const supabase = await requireClassifiedAdmin();

  const { data, error } = await supabase
    .from('classifieds')
    .update({
      status: 'paused',
      rejection_reason: reason,
    })
    .eq('id', classifiedId)
    .eq('status', 'published')
    .select('id')
    .maybeSingle();

  if (error || !data) {
    redirect('/admin/classificados?erro=pausar');
  }

  revalidatePath('/admin/classificados');
  revalidatePath('/classificados');
  revalidatePath('/classificados/meus');
  redirect('/admin/classificados?ok=pausado');
}

