export default async function ClassifiedAdminPage({
  searchParams,
}: AdminPageProps) {
  if (!getSupabasePublicConfig()) {
    redirect('/');
  }

  const query = await searchParams;
  const supabase = await createSupabaseServerClient();
  const { data: claimsData } = await supabase.auth.getClaims();

  if (!hasClassifiedAdminRole(claimsData?.claims)) {
    notFound();
  }

  const [pendingResult, reportsResult] = await Promise.all([
    supabase
      .from('classifieds')
      .select(
        'id, title, description, category_id, neighborhood, price_cents, updated_at, owner_id',
      )
      .eq('status', 'pending_review')
      .order('updated_at', { ascending: true })
      .limit(100),
    supabase
      .from('classified_reports')
      .select(
        'id, reason, details, created_at, classified_id, classifieds(id, title, slug, status)',
      )
      .order('created_at', { ascending: false })
      .limit(100),
  ]);

  if (pendingResult.error) throw pendingResult.error;
  if (reportsResult.error) throw reportsResult.error;

  const reports = (reportsResult.data ?? []) as unknown as ReportRow[];

  return (
    <TerritoryAppShell
      activeId="classifieds"
      territoryName={territoryReleaseScope.city.name}
      contextRail={
        <AdminContextRail
          pendingCount={pendingResult.data?.length ?? 0}
          reportCount={reports.length}
        />
      }
    >
      <main>

      <section className="adminHero">
        <div className="container">
          <p className="eyebrow">Área restrita</p>
          <h1>Moderação de Classificados</h1>
          <p>
            Aprove, devolva para ajustes e analise denúncias sem alterar o conteúdo
            original do anúncio.
          </p>
        </div>
      </section>

      <section className="section container" id="fila">
        {query.ok && (
          <div className="successNotice">
            Ação de moderação concluída.
          </div>
        )}
        {query.erro && (
          <div className="authFeedback authError" role="alert">
            {query.erro === 'motivo'
              ? 'Informe um motivo com pelo menos 10 caracteres.'
              : 'Não foi possível concluir a ação de moderação.'}
          </div>
        )}

        <div className="adminSectionHeading">
          <div>
            <p className="eyebrow">Fila de revisão</p>
            <h2>Pendentes</h2>
          </div>
          <span>{pendingResult.data?.length ?? 0}</span>
        </div>

        {pendingResult.data?.length ? (
          <div className="moderationGrid">
            {pendingResult.data.map((item) => {
              const approveAction = approveClassifiedAction.bind(null, item.id);
              const rejectAction = rejectClassifiedAction.bind(null, item.id);

              return (
                <article className="moderationCard" key={item.id}>
                  <div>
                    <span className="statusPill">Em revisão</span>
                    <h3>{item.title}</h3>
                    <p className="moderationDescription">{item.description}</p>
                    <div className="moderationMeta">
                      <span>{item.category_id}</span>
                      <span>{item.neighborhood || 'Bairro não informado'}</span>
                      <span>
                        {item.price_cents === null
                          ? 'Preço a combinar'
                          : new Intl.NumberFormat('pt-BR', {
                              style: 'currency',
                              currency: 'BRL',
                            }).format(item.price_cents / 100)}
                      </span>
                    </div>
                  </div>

                  <div className="moderationActions">
                    <form action={approveAction}>
                      <button className="primaryButton" type="submit">
                        Aprovar e publicar
                      </button>
                    </form>

                    <form className="moderationReasonForm" action={rejectAction}>
                      <label>
                        Motivo para ajustes
                        <textarea
                          name="reason"
                          rows={3}
                          minLength={10}
                          maxLength={1000}
                          required
                          placeholder="Explique objetivamente o que precisa ser corrigido."
                        />
                      </label>
                      <button className="ghostButton" type="submit">
                        Rejeitar para ajustes
                      </button>
                    </form>
                  </div>
                </article>
              );
            })}
          </div>
        ) : (
          <div className="adminEmptyState">
            Nenhum anúncio aguardando revisão.
          </div>
        )}
      </section>

      <section className="section sectionSoft" id="denuncias">
        <div className="container">
          <div className="adminSectionHeading">
            <div>
              <p className="eyebrow">Segurança</p>
              <h2>Denúncias recentes</h2>
            </div>
            <span>{reports.length}</span>
          </div>

          {reports.length ? (
            <div className="reportList">
              {reports.map((report) => {
                const pauseAction = pausePublishedClassifiedAction.bind(
                  null,
                  report.classified_id,
                );

                return (
                  <article className="reportCard" key={report.id}>
                    <div>
                      <strong>{reportLabels[report.reason] ?? report.reason}</strong>
                      <h3>{report.classifieds?.title ?? 'Anúncio indisponível'}</h3>
                      {report.details && <p>{report.details}</p>}
                      <small>
                        Recebida em{' '}
                        {new Date(report.created_at).toLocaleString('pt-BR')}
                      </small>
                    </div>

                    <div className="reportActions">
                      {report.classifieds?.status === 'published' && (
                        <>
                          <Link
                            className="ghostButton linkButton"
                            href={`/classificados/anuncio/${report.classifieds.slug}`}
                          >
                            Abrir anúncio
                          </Link>
                          <form className="moderationReasonForm" action={pauseAction}>
                            <label>
                              Motivo para retirar do ar
                              <textarea
                                name="reason"
                                rows={2}
                                minLength={10}
                                maxLength={1000}
                                required
                              />
                            </label>
                            <button className="ghostButton" type="submit">
                              Retirar para ajustes
                            </button>
                          </form>
                        </>
                      )}
                    </div>
                  </article>
                );
              })}
            </div>
          ) : (
            <div className="adminEmptyState">
              Nenhuma denúncia registrada.
            </div>
          )}
        </div>
      </section>
      </main>
    </TerritoryAppShell>
  );
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { reportServerError } from '@/core/observability/server-log';
import { territoryReleaseScope } from '@/config/territory-release-scope';
import type { Database } from '@/lib/supabase/database.types';
import { getSupabasePublicConfig } from '@/lib/supabase/config';

export const dynamic = 'force-dynamic';

export async function GET() {
  const checkedAt = new Date().toISOString();
  const config = getSupabasePublicConfig();

  if (!config) {
    return NextResponse.json(
      {
        status: 'degraded',
        database: 'not_configured',
        territory: 'not_configured',
        classifieds: 'not_configured',
        checkedAt,
      },
      {
        status: 503,
        headers: {
          'Cache-Control': 'no-store',
        },
      },
    );
  }

  const supabase = createClient<Database>(
    config.url,
    config.publishableKey,
    {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
      },
    },
  );

  const [territoryResult, classifiedsResult] =
    await Promise.all([
      supabase
        .from('territory_rollout_catalog')
        .select('stage')
        .eq('target_kind', 'group')
        .eq('slug', territoryReleaseScope.group.slug)
        .maybeSingle(),
      supabase
        .from('cities')
        .select('id')
        .eq('slug', territoryReleaseScope.city.slug)
        .eq('state_code', territoryReleaseScope.city.stateCode)
        .eq('is_active', true)
        .maybeSingle(),
    ]);

  const territoryOk =
    !territoryResult.error &&
    Boolean(territoryResult.data);
  const classifiedsOk =
    !classifiedsResult.error &&
    Boolean(classifiedsResult.data);
  const healthy = territoryOk && classifiedsOk;

  if (!territoryOk) {
    reportServerError(
      'health.territory_canary_failed',
      territoryResult.error ??
        new Error('territory_canary_missing'),
    );
  }

  if (!classifiedsOk) {
    reportServerError(
      'health.classifieds_canary_failed',
      classifiedsResult.error ??
        new Error('classifieds_canary_missing'),
    );
  }

  return NextResponse.json(
    {
      status: healthy ? 'ok' : 'degraded',
      database: healthy ? 'ok' : 'unavailable',
      territory: territoryOk ? 'ok' : 'unavailable',
      classifieds: classifiedsOk ? 'ok' : 'unavailable',
      checkedAt,
    },
    {
      status: healthy ? 200 : 503,
      headers: {
        'Cache-Control': 'no-store',
      },
    },
  );
}

import { NextRequest, NextResponse } from 'next/server';
import type { MapLayerId } from '@/core/map';
import { reportServerError } from '@/core/observability/server-log';
import { SupabaseMapDataRepository } from '@/lib/supabase/map-data-repository';
import { createSupabasePublicServerClient } from '@/lib/supabase/public-server';

function numberParam(
  request: NextRequest,
  key: string,
): number {
  const raw = request.nextUrl.searchParams.get(key);
  const value = raw === null ? Number.NaN : Number(raw);

  if (!Number.isFinite(value)) {
    throw new Error(`map_query_invalid:${key}`);
  }

  return value;
}

function parseLayers(
  request: NextRequest,
): MapLayerId[] {
  const raw =
    request.nextUrl.searchParams.get('layers') ??
    'boundaries,public_places';

  const values = raw
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);

  const allowed = new Set<MapLayerId>([
    'boundaries',
    'public_places',
  ]);

  if (
    !values.length ||
    values.some(
      (value) => !allowed.has(value as MapLayerId),
    )
  ) {
    throw new Error('map_query_invalid:layers');
  }

  return [...new Set(values)] as MapLayerId[];
}

function parseCategories(
  request: NextRequest,
): string[] | undefined {
  const raw = request.nextUrl.searchParams.get('categories');

  if (!raw) return undefined;

  const values = raw
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);

  if (
    values.length > 10 ||
    values.some(
      (value) => !/^[a-z0-9_]{1,64}$/.test(value),
    )
  ) {
    throw new Error('map_query_invalid:categories');
  }

  return values.length
    ? [...new Set(values)]
    : undefined;
}

export async function GET(request: NextRequest) {
  const supabase = createSupabasePublicServerClient();

  if (!supabase) {
    return NextResponse.json(
      { error: 'map_data_unavailable' },
      { status: 503 },
    );
  }

  try {
    const repository = new SupabaseMapDataRepository(supabase);
    const data = await repository.loadViewport({
      bounds: {
        west: numberParam(request, 'west'),
        south: numberParam(request, 'south'),
        east: numberParam(request, 'east'),
        north: numberParam(request, 'north'),
      },
      zoom: numberParam(request, 'zoom'),
      layers: parseLayers(request),
      publicPlaceCategories: parseCategories(request),
      placeLimit: 200,
      boundaryLimit: 100,
    });

    return NextResponse.json(data, {
      headers: {
        'Cache-Control':
          'public, s-maxage=60, stale-while-revalidate=300',
      },
    });
  } catch (error) {
    const message =
      error instanceof Error
        ? error.message
        : 'map_query_failed';

    const isInputError =
      message.startsWith('map_bbox_') ||
      message.startsWith('map_zoom_') ||
      message.startsWith('map_categories_') ||
      message.startsWith('map_query_invalid');

    if (!isInputError) {
      reportServerError(
        'territory.map.viewport_api_failed',
        error,
      );
    }

    return NextResponse.json(
      { error: isInputError ? message : 'map_query_failed' },
      { status: isInputError ? 400 : 500 },
    );
  }
}

import { NextResponse, type NextRequest } from 'next/server';
import { isTrustedAuthCallbackOrigin } from '@/lib/auth/origin';
import { safeInternalPath } from '@/lib/safe-path';
import { createSupabaseServerClient } from '@/lib/supabase/server';

export async function GET(request: NextRequest) {
  const url = new URL(request.url);
  const code = url.searchParams.get('code');
  const next = safeInternalPath(
    url.searchParams.get('next'),
    '/',
  );

  if (!isTrustedAuthCallbackOrigin(url.origin)) {
    const failure = new URL('/entrar', url.origin);
    failure.searchParams.set('erro', 'origem_invalida');
    failure.searchParams.set('next', next);
    return NextResponse.redirect(failure);
  }

  if (code) {
    const supabase = await createSupabaseServerClient();
    const { error } = await supabase.auth.exchangeCodeForSession(code);

    if (!error) {
      return NextResponse.redirect(new URL(next, url.origin));
    }
  }

  const failure = new URL('/entrar', url.origin);
  failure.searchParams.set('erro', 'confirmacao_falhou');
  failure.searchParams.set('next', next);
  return NextResponse.redirect(failure);
}

import { NextResponse, type NextRequest } from 'next/server';
import { isTrustedAuthRequestOrigin } from '@/lib/auth/origin';
import { createSupabaseServerClient } from '@/lib/supabase/server';

export async function POST(request: NextRequest) {
  const origin = request.headers.get('origin');

  if (!isTrustedAuthRequestOrigin(origin)) {
    return NextResponse.json(
      { error: 'auth_origin_invalid' },
      {
        status: 403,
        headers: {
          'Cache-Control': 'no-store',
        },
      },
    );
  }

  const supabase = await createSupabaseServerClient();
  await supabase.auth.signOut();

  return NextResponse.redirect(new URL('/', request.url), {
    status: 303,
  });
}

