  published: 'Publicado',
  paused: 'Pausado',
  sold: 'Vendido',
  rejected: 'Precisa de ajustes',
  archived: 'Arquivado',
};

function money(value: number | null) {
  if (value === null) return 'Preço a combinar';

  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value / 100);
}

export default async function MyClassifiedsPage({
  searchParams,
