          <h1>Favoritos</h1>
          <p>Guarde anúncios publicados para encontrar de novo com facilidade.</p>
          <Link className="primaryButton linkButton" href="/classificados">
            Explorar Classificados
          </Link>
        </div>
      </section>

      <section className="accountMetricStrip container" aria-label="Resumo dos favoritos">
        <article className="accountMetric">
          <span>Disponíveis</span>
          <strong>{items.length}</strong>
          <small>Anúncios públicos salvos</small>
        </article>
        <article className="accountMetric">
          <span>Indisponíveis</span>
          <strong>{unavailableCount}</strong>
          <small>Fora da área pública agora</small>
        </article>
      </section>

      <section className="section container">
        {items.length ? (
          <div className="publicClassifiedGrid">
            {items.map((item) => {
              const removeAction = toggleFavoriteAction.bind(
                null,
                item.id,
                '/favoritos',
              );

              return (
                <div className="favoriteCardWrap" key={item.id}>
                  <ClassifiedCard
                    item={item}
                    imageUrl={imageUrls[item.id] ?? null}
                  />
                  <form action={removeAction}>
                    <button className="favoriteRemoveButton" type="submit">
                      Remover dos favoritos
                    </button>
                  </form>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="classifiedEmptyState">
            <span className="emptyIcon" aria-hidden="true"><NavigationIcon name="favorite" /></span>
            <div>
              <h3>Você ainda não salvou nenhum anúncio.</h3>
              <p>
                Quando encontrar algo interessante, use “Salvar nos favoritos”.
              </p>
            </div>
            <Link className="primaryButton linkButton" href="/classificados">
              Explorar anúncios
            </Link>
          </div>
        )}
      </section>

      </main>
    </TerritoryAppShell>
  );
}

:root {
  --ink: #0b1830;
  --muted: #657184;
  --line: #e6ecea;
  --surface: #ffffff;
  --soft: #f4faf8;
  --brand: #0c9470;
  --brand-dark: #05624d;
  --brand-light: #62e6b6;
  --accent-warm: #e2a447;
  --accent-coral: #d96b55;
  --shadow: 0 16px 50px rgba(11, 24, 48, .10);
  --radius: 24px;
  --container: 1180px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--ink);
  background: var(--surface);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}
button, input { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
h1, h2, h3, p { margin-top: 0; }
.container { width: min(var(--container), calc(100% - 32px)); margin: 0 auto; }
.srOnly { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

.brand { display: flex; align-items: center; gap: 10px; min-width: max-content; }
.brandMark {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background:
    linear-gradient(145deg, var(--brand), #08745b);
  color: #ffffff;
  box-shadow: 0 9px 22px rgba(12,148,112,.20);
}
.brandMark svg {
  width: 23px;
  height: 23px;
}
.brandPin {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.65;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.brandHeart {
  fill: var(--accent-coral);
  stroke: #ffffff;
  stroke-width: .65;
  stroke-linejoin: round;
}
.brand strong { display: block; font-size: 1.12rem; line-height: 1; letter-spacing: -.02em; }
.brand small { display: block; margin-top: 3px; color: var(--muted); font-size: .61rem; }
.linkButton { display: inline-flex; align-items: center; justify-content: center; width: fit-content; }

.hero { background: linear-gradient(140deg, #effbf7 0%, #f7fcfb 50%, #e5f7f0 100%); overflow: hidden; }
.heroGrid { display: grid; gap: 28px; padding: 52px 0 0; }
.eyebrow { color: var(--brand); font-weight: 800; text-transform: uppercase; letter-spacing: .12em; font-size: .72rem; margin-bottom: 12px; }
.hero h1 { font-size: clamp(2.35rem, 11vw, 4.8rem); line-height: .98; letter-spacing: -.055em; max-width: 820px; margin-bottom: 20px; }
.hero h1 em { font-style: normal; color: var(--brand); }
.heroText { color: #405067; font-size: 1.03rem; line-height: 1.65; max-width: 690px; }

.searchButton, .primaryButton, .ghostButton {
  border: 0;
  border-radius: 14px;
  min-height: 44px;
  padding: 0 18px;
  font-weight: 800;
  cursor: pointer;
  transition:
    transform .16s ease,
    box-shadow .16s ease,
    border-color .16s ease,
    background-color .16s ease;
}
.searchButton, .primaryButton {
  color: white;
  background: linear-gradient(135deg, var(--brand), #13a77f);
  box-shadow: 0 10px 24px rgba(12,148,112,.18);
}
.ghostButton {
  color: var(--ink);
  background: rgba(255,255,255,.78);
  border: 1px solid var(--line);
}
.searchButton:hover, .primaryButton:hover, .ghostButton:hover {
  transform: translateY(-1px);
}
.ghostButton:hover {
  border-color: #b9d7cc;
  background: #ffffff;
}
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid rgba(12,148,112,.22);
  outline-offset: 3px;
}

.section { padding: 58px 0; }
.sectionSoft { background: var(--soft); }
.sectionHeading { display: flex; align-items: end; justify-content: space-between; gap: 20px; margin-bottom: 24px; }
.sectionHeading h2 { font-size: clamp(1.65rem, 7vw, 2.6rem); line-height: 1.05; letter-spacing: -.035em; margin-bottom: 8px; }
.sectionHeading p:not(.eyebrow) { color: var(--muted); line-height: 1.55; }
.sectionHeading > a { display: none; color: var(--brand); font-weight: 800; }

footer { background: #075344; color: white; padding: 34px 0 100px; }
footer .brand small { color: #b9ded4; }
.footerInner { display: grid; gap: 20px; }
.footerInner p { color: #cce7e0; margin: 0; }
.footerInner > div { display: flex; gap: 18px; font-size: .8rem; }

.mobileTabbar {
  position: fixed;
  left: 10px;
  right: 10px;
  bottom: max(10px, env(safe-area-inset-bottom));
  z-index: 60;
  height: 66px;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  border: 1px solid rgba(212,225,220,.92);
  border-radius: 21px;
  background: rgba(255,255,255,.95);
  backdrop-filter: blur(20px);
  box-shadow: 0 16px 44px rgba(5,43,34,.18);
}
.mobileTabbar a {
  position: relative;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
  color: #667484;
  font-size: .58rem;
  font-weight: 800;
}
.mobileTabbar a::before {
  content: "";
  position: absolute;
  top: 5px;
  width: 26px;
  height: 3px;
  border-radius: 999px;
  background: transparent;
}
.mobileTabbar a.active { color: var(--brand-dark); }
.mobileTabbar a.active::before { background: var(--brand); }
.mobileTabbar svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.mobileTabbar a > span { font-size: .58rem; }

@media (min-width: 720px) {
  .container { width: min(var(--container), calc(100% - 56px)); }
  .sectionHeading > a { display: block; }
}

@media (min-width: 980px) {
  .mobileTabbar { display: none; }
  .heroGrid { grid-template-columns: 1.05fr .95fr; align-items: stretch; padding-top: 0; }
  .heroCopy { padding: 78px 0 60px; }
  .section { padding: 86px 0; }
  footer { padding-bottom: 34px; }
  .footerInner { grid-template-columns: auto 1fr auto; align-items: center; }
}


.internalHero h1,
.classifiedHero h1,
.statePage h1 {
  font-size: clamp(2rem, 9vw, 4rem);
  line-height: 1;
  letter-spacing: -.05em;
}
.internalHero p:not(.eyebrow),
.classifiedHero p:not(.eyebrow),
.statePage p {
  color: var(--muted);
  line-height: 1.65;
}
.narrow { max-width: 820px; }

