  color: var(--brand-dark);
  font-size: 1.45rem;
  line-height: 1;
}

.summary span {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: .65rem;
}

.filters {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.filterHeading {
  grid-column: 1 / -1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 2px;
}

.filterHeading > strong,
.placeListHeader strong {
  font-size: .72rem;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.filterHeading > span,
.placeListHeader span,
.placeListHeader small {
  color: var(--muted);
  font-size: .64rem;
}

.filters button {
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: white;
  color: #455368;
  font: inherit;
  cursor: pointer;
  transition:
    border-color .16s ease,
    background-color .16s ease,
    transform .16s ease;
}

.filters button:hover {
  border-color: #b8c8c2;
  transform: translateY(-1px);
}

.filters button:focus-visible,
.placeButton:focus-visible {
  outline: 3px solid rgba(12, 148, 112, .24);
  outline-offset: 2px;
}

.filters .filterActive {
  color: var(--brand-dark);
  box-shadow: 0 8px 20px rgba(11,72,57,.045);
}

.filters .filterEducationActive {
  border-color: #9fd5c1;
  background: #edf9f4;
}

.filters .filterHealthActive {
  border-color: #efc3b9;
  background: #fff4f1;
  color: #8b4336;
}

.filterButtonText {
  min-width: 0;
  display: grid;
  gap: 2px;
  text-align: left;
}

.filterButtonText strong {
  font-size: .72rem;
}

.filterButtonText small {
  color: var(--muted);
  font-size: .6rem;
  font-weight: 650;
}

.educationDot,
.healthDot {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.educationDot {
  background: var(--brand);
}

.healthDot {
  background: #d8563f;
}

.mapStage {
  grid-area: map;
  position: relative;
  min-height: 56svh;
  overflow: hidden;
  background: #dfe9e5;
  isolation: isolate;
}

.mapStage::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  box-shadow: inset 0 0 0 1px rgba(11,24,48,.045);
}

.map {
  position: absolute;
  inset: 0;
}

.mapHud {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 62px;
  z-index: 4;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  pointer-events: none;
}

.mapHud span {
  padding: 7px 9px;
  border: 1px solid rgba(255, 255, 255, .82);
  border-radius: 999px;
  background: rgba(255, 255, 255, .93);
  color: #26384a;
  font-size: .62rem;
  font-weight: 800;
  box-shadow: 0 8px 24px rgba(11, 24, 48, .11);
  backdrop-filter: blur(10px);
}

.mapHud .mapStatusLoading {
  color: var(--brand-dark);
}

.mapError {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 14px;
  z-index: 4;
  padding: 12px 14px;
  border: 1px solid #eed3cd;
  border-radius: 14px;
  background: rgba(255, 248, 246, .96);
  color: #873e32;
  font-size: .75rem;
  font-weight: 750;
  box-shadow: var(--shadow);
}

.placeList {
  display: grid;
  gap: 9px;
}

.placeListHeader {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: end;
  margin-bottom: 4px;
}

.placeListHeader > div {
  display: grid;
  gap: 3px;
}

.placeList article {
  border: 1px solid #e0e9e6;
  border-radius: 15px;
  background: #ffffff;
  overflow: hidden;
  box-shadow: 0 7px 20px rgba(11,72,57,.025);
}

.placeButton {
  width: 100%;
  min-height: 52px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  padding: 13px 12px;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  font: inherit;
  cursor: pointer;
  transition: background-color .16s ease;
}

.placeButton:hover {
  background: #f3faf7;
}

.placeButton > .educationDot,
.placeButton > .healthDot {
  margin-top: 5px;
}

.placeButton strong {
  display: block;
  margin-bottom: 3px;
  font-size: .78rem;
  line-height: 1.3;
}

.placeButton small {
  color: var(--muted);
  font-size: .63rem;
}

.placeButton p {
  margin: 4px 0 0;
  color: #5a6878;
  font-size: .67rem;
  line-height: 1.4;
}

.placeArrow {
  color: #819089;
  font-size: .75rem;
  transition: transform .16s ease;
}

.placeButton:hover .placeArrow {
  transform: translate(2px, -2px);
}

.empty,
.provenance {
  color: var(--muted);
  font-size: .69rem;
  line-height: 1.5;
}

.empty {
  margin: 0;
  padding: 18px;
  border: 1px dashed #cadbd5;
  border-radius: 15px;
  background: #f8fbfa;
}

.provenance {
  margin: 0;
  padding-top: 5px;
}

.visuallyHidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.unavailable {
  min-height: calc(100svh - 68px);
  display: grid;
  align-items: center;
  padding: 44px 0 100px;
  background:
    radial-gradient(circle at 88% 12%, rgba(98,230,182,.16), transparent 28%),
    linear-gradient(145deg, #f0faf6, #fff);
}

.unavailableCard {
  max-width: 720px;
  padding: 26px;
  border: 1px solid #dce9e4;
  border-radius: 24px;
  background: rgba(255,255,255,.9);
  box-shadow: 0 18px 48px rgba(11,72,57,.06);
}

.unavailableActions {
