    padding-left: 28px;
    padding-right: 28px;
  }
}

@media (min-width: 980px) {
  .shell {
    grid-template-columns: 350px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas:
      "controls map"
      "results map";
    height: calc(100svh - 74px);
    min-height: 0;
  }

  .controlsPane {
    min-height: 0;
    padding: 26px 22px 20px;
    border-right: 1px solid #dfe9e5;
    border-bottom: 1px solid #dfe9e5;
  }

  .resultsPane {
    min-height: 0;
    overflow-y: auto;
    padding: 18px 22px 34px;
    border-top: 0;
    border-right: 1px solid #dfe9e5;
    scrollbar-color: #bdd6cd transparent;
  }

  .controlsPane h1 {
    font-size: 2.35rem;
  }

  .mapStage {
    min-height: 0;
  }

  .mapHud {
    top: 16px;
    left: 16px;
    right: 72px;
  }
}

@media (prefers-reduced-motion: reduce) {
