export default async function MessagesPage() {
  if (!getSupabasePublicConfig()) {
    redirect('/entrar?erro=indisponivel&next=/mensagens');
  }

  const supabase = await createSupabaseServerClient();
  const { data: claimsData } = await supabase.auth.getClaims();
  const userId = claimsData?.claims?.sub;

  if (typeof userId !== 'string') {
    redirect('/entrar?next=/mensagens');
  }

  const { data, error } = await supabase
    .from('classified_conversations')
    .select('id, buyer_id, seller_id, updated_at, classifieds(title, slug, status)')
    .or(`buyer_id.eq.${userId},seller_id.eq.${userId}`)
    .order('updated_at', { ascending: false });

  if (error) throw error;

  const conversations = (data ?? []) as unknown as ConversationRow[];
  const sellerConversationCount = conversations.filter(
    (conversation) => conversation.seller_id === userId,
  ).length;
  const buyerConversationCount =
    conversations.length - sellerConversationCount;

  return (
    <TerritoryAppShell
      activeId="classifieds"
      territoryName={territoryReleaseScope.city.name}
      contextRail={<AccountContextRail active="messages" />}
    >
      <main>

      <section className="internalHero compactInternalHero">
        <div className="container narrow">
          <p className="eyebrow">Contato seguro</p>
          <h1>Mensagens</h1>
          <p>
            Converse dentro do Achegue-se sem publicar telefone ou e-mail no anúncio.
          </p>
        </div>
      </section>

      <section className="accountMetricStrip container" aria-label="Resumo das mensagens">
        <article className="accountMetric">
          <span>Conversas</span>
          <strong>{conversations.length}</strong>
          <small>Total da sua conta</small>
        </article>
        <article className="accountMetric">
          <span>Como anunciante</span>
          <strong>{sellerConversationCount}</strong>
          <small>Interesse nos seus anúncios</small>
        </article>
        <article className="accountMetric">
          <span>Como interessado</span>
          <strong>{buyerConversationCount}</strong>
          <small>Conversas que você iniciou</small>
        </article>
      </section>

      <section className="section container">
        {conversations.length ? (
          <div className="conversationList">
            {conversations.map((conversation) => {
              const isSeller = conversation.seller_id === userId;

              return (
                <Link
                  className="conversationCard"
                  href={`/mensagens/${conversation.id}`}
                  key={conversation.id}
                >
                  <div>
                    <span className="statusPill">
                      {isSeller ? 'Seu anúncio' : 'Seu interesse'}
                    </span>
                    <h2>{conversation.classifieds?.title ?? 'Classificado'}</h2>
                    <p>
                      {conversation.classifieds?.status === 'published'
                        ? 'Anúncio publicado'
                        : 'Anúncio não está mais público'}
                    </p>
                  </div>
                  <div className="conversationCardMeta">
                    <span>
                      {new Date(conversation.updated_at).toLocaleDateString('pt-BR')}
                    </span>
                    <strong>Ver conversa →</strong>
                  </div>
                </Link>
              );
            })}
          </div>
        ) : (
          <div className="classifiedEmptyState">
            <span className="emptyIcon" aria-hidden="true"><NavigationIcon name="messages" /></span>
            <div>
              <h3>Nenhuma conversa ainda.</h3>
              <p>
                Abra um anúncio publicado e envie uma mensagem ao anunciante.
              </p>
            </div>
            <Link className="primaryButton linkButton" href="/classificados">
              Explorar Classificados
            </Link>
          </div>
        )}
      </section>

      </main>
    </TerritoryAppShell>
  );
}

