function combineBoundaryBounds(
  boundaries: TerritoryBoundary[],
): BoundingBox {
  if (!boundaries.length) {
    throw new Error('territory_home_boundary_missing');
  }

  let west = Number.POSITIVE_INFINITY;
  let south = Number.POSITIVE_INFINITY;
  let east = Number.NEGATIVE_INFINITY;
  let north = Number.NEGATIVE_INFINITY;

  for (const boundary of boundaries) {
    for (const ring of boundary.bboxGeojson.coordinates) {
      for (const [longitude, latitude] of ring) {
        west = Math.min(west, longitude);
        south = Math.min(south, latitude);
        east = Math.max(east, longitude);
        north = Math.max(north, latitude);
      }
    }
  }

  if (
    !Number.isFinite(west) ||
    !Number.isFinite(south) ||
    !Number.isFinite(east) ||
    !Number.isFinite(north)
  ) {
    throw new Error('territory_home_bounds_invalid');
  }

  return {
    west,
    south,
    east,
    north,
  };
}

function buildHomeMapData({
  bounds,
  boundaries,
  places,
  members,
  scopeIds,
}: {
  bounds: BoundingBox;
  boundaries: TerritoryBoundary[];
  places: Awaited<
    ReturnType<
      SupabaseTerritoryDataRepository['listPublicPlacesForTerritories']
    >
  >;
  members: TerritoryReference[];
  scopeIds: string[];
}): MapViewportData {
  const scopeIdSet = new Set(scopeIds);
  const memberById = new Map(
    members.map((member) => [member.id, member]),
  );

  return {
    bounds,
    boundaries: boundaries
      .filter((boundary) =>
        scopeIdSet.has(boundary.territoryId),
      )
      .map((boundary) => ({
        id: boundary.territoryId,
        territoryId: boundary.territoryId,
        territorySlug: boundary.slug,
        territoryName: boundary.name,
        geographicPath: boundary.geographicPath,
        geometry: boundary.geojson,
        bboxGeometry: boundary.bboxGeojson,
        areaInSquareMeters:
          boundary.areaInSquareMeters,
        source: {
          key: 'territory-boundary',
          providerName: boundary.sourceName,
          datasetName: boundary.sourceName,
          sourceUrl: boundary.sourceUrl ?? '',
          attribution: boundary.sourceName,
        },
      })),
    points: places.flatMap((place) => {
      if (
        !scopeIdSet.has(place.territoryId) ||
        place.latitude === null ||
        place.longitude === null
      ) {
        return [];
      }

      const territory = memberById.get(
        place.territoryId,
      );

      if (!territory) return [];

      return [{
        id: place.id,
        territoryId: place.territoryId,
        territorySlug: territory.slug,
        territoryName: territory.name,
        geographicPath: territory.geographicPath,
        kind: place.categoryKey,
        kindLabel: place.categoryLabel,
        coordinates: {
          latitude: place.latitude,
          longitude: place.longitude,
        },
        title: place.name,
        description: place.description,
        address: place.addressText,
        phone: place.phone,
        website: place.website,
        source: {
          key: place.provenance.sourceKey,
          providerName:
            place.provenance.providerName,
          datasetName:
            place.provenance.datasetName,
          sourceUrl: place.provenance.sourceUrl,
          attribution:
            place.provenance.attribution,
        },
      }];
    }),
  };
}

function buildNeighborhood(
  member: TerritoryReference,
  selectedId: string | null,
  facts: Awaited<
    ReturnType<
      SupabaseTerritoryDataRepository['listFactsForTerritories']
    >
  >,
  places: Awaited<
    ReturnType<
      SupabaseTerritoryDataRepository['listPublicPlacesForTerritories']
    >
  >,
): TerritoryHomeNeighborhood {
  const ids = [member.id];

  return {
    id: member.id,
    slug: member.slug,
    name: member.name,
    selected: member.id === selectedId,
    population: aggregateNumericMetric(
      ids,
      'population_total',
      facts,
    ),
    households: aggregateNumericMetric(
      ids,
      'households_total',
      facts,
    ),
    educationCount: countPlaces(
      ids,
      places,
      'education',
    ),
    healthCount: countPlaces(
      ids,
      places,
      'health',
    ),
    publicPlaceCount: countPlaces(ids, places),
  };
}

export async function loadTerritoryHomeData(
  supabase: SupabaseClient<Database>,
  requestedNeighborhoodSlug?: string,
): Promise<TerritoryHomeData> {
  const territoryRepository =
    new SupabaseTerritoryRepository(supabase);
  const dataRepository =
    new SupabaseTerritoryDataRepository(supabase);
  const boundaryRepository =
    new SupabaseTerritoryBoundaryRepository(supabase);
  const rolloutRepository =
    new SupabaseTerritoryRolloutRepository(supabase);

  const city =
    await territoryRepository.findByGeographicPath(
      territoryReleaseScope.city.geographicPath,
    );

  if (!city) {
    throw new Error('territory_home_city_missing');
  }

  const group =
    await territoryRepository.findGroupBySlug(
      city.id,
      territoryReleaseScope.group.slug,
    );

  if (!group) {
    throw new Error('territory_home_group_missing');
  }

  const members =
    await territoryRepository.findGroupMembers(group.id);

  if (!members.length) {
    throw new Error('territory_home_members_missing');
  }

  const selectedMember =
    requestedNeighborhoodSlug
      ? members.find(
          (member) =>
            member.slug === requestedNeighborhoodSlug,
        ) ?? null
      : null;

  if (
    requestedNeighborhoodSlug &&
    !selectedMember
  ) {
    throw new Error(
      'territory_home_neighborhood_invalid',
    );
  }

  const allMemberIds = members.map((member) => member.id);
  const scopeIds = selectedMember
    ? [selectedMember.id]
    : allMemberIds;

  const [
    facts,
    places,
    boundaries,
    rollout,
  ] = await Promise.all([
    dataRepository.listFactsForTerritories(
      allMemberIds,
      [
        'population_total',
        'households_total',
      ],
    ),
    dataRepository.listPublicPlacesForTerritories(
      allMemberIds,
      ['education', 'health'],
      200,
    ),
    boundaryRepository.findByTerritoryIds(allMemberIds),
    selectedMember
      ? rolloutRepository.findByTarget(
          'territory',
          selectedMember.id,
        )
      : rolloutRepository.findByTarget(
          'group',
          group.id,
        ),
  ]);

  if (!rollout) {
    throw new Error('territory_home_rollout_missing');
  }

  const scopeBoundaryIds = new Set(scopeIds);
  const scopeBoundaries = boundaries.filter((boundary) =>
    scopeBoundaryIds.has(boundary.territoryId),
  );
  const bounds = combineBoundaryBounds(scopeBoundaries);

  const mapData = buildHomeMapData({
    bounds,
    boundaries: scopeBoundaries,
    places,
    members,
    scopeIds,
  });

  const neighborhoods = members.map((member) =>
    buildNeighborhood(
      member,
      selectedMember?.id ?? null,
      facts,
      places,
    ),
  );

  return {
    scope: {
      kind: selectedMember ? 'territory' : 'group',
      slug: selectedMember?.slug ?? group.slug,
      name: selectedMember?.name ?? group.name,
      rolloutStage: rollout.stage,
      memberCount: selectedMember ? 1 : members.length,
      population: aggregateNumericMetric(
        scopeIds,
        'population_total',
        facts,
      ),
      households: aggregateNumericMetric(
        scopeIds,
        'households_total',
        facts,
      ),
      educationCount: countPlaces(
        scopeIds,
        places,
        'education',
      ),
      healthCount: countPlaces(
        scopeIds,
        places,
        'health',
      ),
      publicPlaceCount: countPlaces(scopeIds, places),
    },
    neighborhoods,
    sources: collectSources(
      scopeIds,
      facts,
      places,
    ),
    mapData,
  };
}

