import {
  Map as MapLibreMap,
} from 'maplibre-gl';
import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import type { MapViewportData } from '@/core/map';
import {
  addTerritoryMapLayers,
  configureMapLibreWorker,
  MAPLIBRE_STYLE_URL,
} from '@/integrations/map/maplibre-shared';
import styles from './territory-mini-map.module.css';

type TerritoryMiniMapProps = {
  data: MapViewportData;
  ariaLabel?: string;
  className?: string;
  includePoints?: boolean;
};

export function TerritoryMiniMap({
  data,
  ariaLabel = 'Prévia do mapa territorial',
  className,
  includePoints = true,
}: TerritoryMiniMapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [failed, setFailed] = useState(false);

  const center = useMemo(
    () => ({
      longitude: (data.bounds.west + data.bounds.east) / 2,
      latitude: (data.bounds.south + data.bounds.north) / 2,
    }),
    [data.bounds],
  );

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    configureMapLibreWorker();

    const map = new MapLibreMap({
      container: containerRef.current,
      style: MAPLIBRE_STYLE_URL,
      center: [center.longitude, center.latitude],
      zoom: 13,
      minZoom: 10,
      maxZoom: 19,
      interactive: false,
      attributionControl: false,
    });

    mapRef.current = map;
    map.getCanvas().tabIndex = -1;
    map.getCanvas().setAttribute('aria-hidden', 'true');

    map.on('load', () => {
      addTerritoryMapLayers(map, data, {
        clustered: false,
        compact: true,
        includePoints,
      });

      map.fitBounds(
        [
          [data.bounds.west, data.bounds.south],
          [data.bounds.east, data.bounds.north],
        ],
        {
          padding: 16,
          duration: 0,
        },
      );
    });

    map.on('error', () => {
      setFailed(true);
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, [
    center.latitude,
    center.longitude,
    data,
    includePoints,
  ]);

  const rootClassName = [
    styles.root,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  if (failed) {
    return (
      <div
        className={`${rootClassName} ${styles.fallback}`}
        role="img"
        aria-label={ariaLabel}
      >
        <span>Mapa indisponível</span>
        <small>Os dados territoriais continuam acessíveis em texto.</small>
      </div>
    );
  }

  return (
    <div
      className={rootClassName}
      role="img"
      aria-label={ariaLabel}
    >
      <div
        ref={containerRef}
        className={styles.canvas}
        aria-hidden="true"
      />
    </div>
  );
}

const LOCAL_HOSTS = new Set([
  'localhost',
  '127.0.0.1',
  '[::1]',
]);

function exactOrigin(
  value: string | null,
) {
  if (!value) return null;

  try {
    const url = new URL(value);

    return url.origin === value
      ? url.origin
      : null;
  } catch {
    return null;
  }
}

export function vercelDeploymentOrigin(
  vercelMarker: string | undefined,
  vercelUrl: string | undefined,
) {
  if (vercelMarker !== '1' || !vercelUrl?.trim()) {
    return null;
  }

  const hostname = vercelUrl.trim().toLowerCase();

  if (
    hostname.includes('/') ||
    hostname.includes(':') ||
    !hostname.endsWith('.vercel.app')
  ) {
    return null;
  }

  return exactOrigin(`https://${hostname}`);
}

export function trustedAuthOrigin(
  siteUrl: string | null,
  deploymentOrigin: string | null,
  requestOrigin: string | null,
) {
  const origin = exactOrigin(requestOrigin);

  if (!origin) return null;

  if (
    origin === siteUrl ||
    origin === deploymentOrigin
  ) {
    return origin;
  }

  if (siteUrl || deploymentOrigin) {
    return null;
  }

  const url = new URL(origin);

  if (
    url.protocol === 'http:' &&
    LOCAL_HOSTS.has(url.hostname)
  ) {
    return origin;
  }

  return null;
}

export function trustedAuthCallbackOrigin(
  siteUrl: string | null,
  deploymentOrigin: string | null,
  requestOrigin: string,
) {
  return trustedAuthOrigin(
    siteUrl,
    deploymentOrigin,
    requestOrigin,
  ) === requestOrigin;
}

import { getSiteUrl } from '@/lib/site-url';
import {
  trustedAuthCallbackOrigin,
  trustedAuthOrigin,
  vercelDeploymentOrigin,
} from '@/lib/auth/origin-core';

function getVercelDeploymentOrigin() {
  return vercelDeploymentOrigin(
    process.env.VERCEL,
    process.env.VERCEL_URL,
  );
}

export function getTrustedAuthOrigin(
  requestOrigin: string | null,
) {
  return trustedAuthOrigin(
    getSiteUrl(),
    getVercelDeploymentOrigin(),
    requestOrigin,
  );
}

export function isTrustedAuthCallbackOrigin(
  requestOrigin: string,
) {
  return trustedAuthCallbackOrigin(
    getSiteUrl(),
    getVercelDeploymentOrigin(),
    requestOrigin,
  );
}

export function isTrustedAuthRequestOrigin(
  requestOrigin: string | null,
) {
  return Boolean(
    requestOrigin &&
      trustedAuthCallbackOrigin(
        getSiteUrl(),
        getVercelDeploymentOrigin(),
        requestOrigin,
      ),
  );
}

type ClaimsWithAppMetadata = {
  app_metadata?: unknown;
};

export function hasClassifiedAdminRole(claims: unknown) {
  if (!claims || typeof claims !== 'object') return false;

  const appMetadata = (claims as ClaimsWithAppMetadata).app_metadata;

  if (!appMetadata || typeof appMetadata !== 'object') return false;

  return (
    (appMetadata as { role?: unknown }).role === 'classified_admin'
  );
}

export function parseHttpOrigin(
  value: string | undefined,
): string | null {
  const raw = value?.trim();

  if (!raw) return null;

  try {
    const url = new URL(raw);

    if (
      (url.protocol !== 'https:' &&
        url.protocol !== 'http:') ||
      url.username ||
      url.password ||
      url.search ||
      url.hash ||
      (url.pathname !== '/' && url.pathname !== '')
    ) {
      return null;
    }

    return url.origin;
  } catch {
    return null;
  }
}

const INTERNAL_BASE = 'https://acheguese.invalid';
const UNSAFE_ENCODED_PATH =
  /%(?:2f|5c|0[0-9a-f]|1[0-9a-f]|7f)/i;
const UNSAFE_DECODED_PATH =
  /[\\\u0000-\u001f\u007f]/;

function hasUnsafePathCanonicalization(
  pathname: string,
) {
  let current = pathname;

  for (let pass = 0; pass < 3; pass += 1) {
    if (
      current.startsWith('//') ||
      UNSAFE_ENCODED_PATH.test(current) ||
      UNSAFE_DECODED_PATH.test(current)
    ) {
      return true;
    }

    let decoded: string;

    try {
      decoded = decodeURIComponent(current);
    } catch {
      return true;
    }

    if (decoded === current) {
      return false;
    }

    current = decoded;
  }

  return (
    current.startsWith('//') ||
    UNSAFE_ENCODED_PATH.test(current) ||
    UNSAFE_DECODED_PATH.test(current)
  );
}

export function safeInternalPath(
  value: unknown,
  fallback = '/',
) {
  if (typeof value !== 'string') return fallback;

  const candidate = value.trim();

  if (
    !candidate.startsWith('/') ||
    candidate.startsWith('//') ||
    candidate.includes('\\')
  ) {
    return fallback;
  }

  try {
    const url = new URL(candidate, INTERNAL_BASE);

    if (
      url.origin !== INTERNAL_BASE ||
      hasUnsafePathCanonicalization(url.pathname)
    ) {
      return fallback;
    }

    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    return fallback;
  }
}

