export type ClassifiedDraftValidationResult =
  | {
      ok: true;
      value: ClassifiedDraftInput;
    }
  | {
      ok: false;
      issues: ClassifiedValidationIssue[];
    };

const conditions = new Set<ClassifiedCondition>([
  'new',
  'like_new',
  'used',
  'for_parts',
]);

function stringValue(value: FormDataEntryValue | null): string {
  return typeof value === 'string' ? value.trim() : '';
}

export function validateClassifiedFormData(
  formData: FormData,
): ClassifiedDraftValidationResult {
  const issues: ClassifiedValidationIssue[] = [];

  const title = stringValue(formData.get('title'));
  const description = stringValue(formData.get('description'));
  const categoryValue = stringValue(formData.get('categoryId'));
  const conditionValue = stringValue(formData.get('condition'));
  const priceValue = stringValue(formData.get('price'));
  const cityId = stringValue(formData.get('cityId'));
  const neighborhoodValue = stringValue(formData.get('neighborhood'));
  const priceInCents = parseClassifiedPriceInCents(priceValue);

  if (title.length < 5 || title.length > 120) {
    issues.push({ field: 'title', code: 'invalid_length' });
  }

  if (description.length < 20 || description.length > 5000) {
    issues.push({ field: 'description', code: 'invalid_length' });
  }

  if (!isClassifiedCategoryId(categoryValue)) {
    issues.push({ field: 'categoryId', code: 'invalid_category' });
  }

  if (!conditions.has(conditionValue as ClassifiedCondition)) {
    issues.push({ field: 'condition', code: 'invalid_condition' });
  }

  if (priceInCents === undefined) {
    issues.push({ field: 'price', code: 'invalid_price' });
  }

  if (!/^\d+$/.test(cityId)) {
    issues.push({ field: 'cityId', code: 'invalid_city' });
  }

  if (neighborhoodValue.length > 120) {
    issues.push({ field: 'neighborhood', code: 'invalid_length' });
  }

  if (issues.length > 0) {
    return {
      ok: false,
      issues,
    };
  }

  return {
    ok: true,
    value: {
      title,
      description,
      categoryId: categoryValue as ClassifiedCategoryId,
      condition: conditionValue as ClassifiedCondition,
      priceInCents: priceInCents ?? null,
      cityId,
      neighborhood: neighborhoodValue || null,
    },
  };
}

export function parseClassifiedPriceInCents(
  value: string,
): number | null | undefined {
  if (!value) {
    return null;
  }

  const normalized = value
    .replace(/\s/g, '')
    .replace(/^R\$/i, '')
    .replace(/\./g, '')
    .replace(',', '.');

  if (!/^\d+(?:\.\d{1,2})?$/.test(normalized)) {
    return undefined;
  }

  const [whole, fraction = ''] = normalized.split('.');
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));

  if (!Number.isSafeInteger(cents) || cents < 0) {
    return undefined;
  }

  return cents;
}

export type ClassifiedStatus =
  | 'draft'
  | 'pending_review'
  | 'published'
  | 'paused'
  | 'sold'
  | 'rejected'
  | 'archived';

export type ClassifiedCondition = 'new' | 'like_new' | 'used' | 'for_parts';

export type Money = {
  amountInCents: number;
  currency: 'BRL';
};

export type ClassifiedLocation = {
  cityId: string;
  cityName: string;
  stateCode: string;
  neighborhood?: string | null;
  latitude?: number;
  longitude?: number;
};

export type ClassifiedMedia = {
  id: string;
  storageKey: string;
  alt: string;
  position: number;
};

export type Classified = {
  id: string;
  ownerId: string;
  categoryId: string;
  slug: string;
  title: string;
  description: string;
  condition: ClassifiedCondition;
  price: Money | null;
  location: ClassifiedLocation;
  media: ClassifiedMedia[];
  status: ClassifiedStatus;
  createdAt: string;
  updatedAt: string;
  publishedAt: string | null;
};

export type ClassifiedListItem = Pick<
  Classified,
  'id' | 'slug' | 'title' | 'price' | 'condition' | 'location' | 'status' | 'publishedAt'
> & {
  cover: ClassifiedMedia | null;
};

export type ClassifiedSearchInput = {
  query?: string;
  categoryId?: string;
  cityId?: string;
  minPriceInCents?: number;
  maxPriceInCents?: number;
  condition?: ClassifiedCondition;
  cursor?: string;
  limit?: number;
};

export type ClassifiedSearchPage = {
  items: ClassifiedListItem[];
  nextCursor: string | null;
};

import type { ClassifiedCondition } from '@/modules/classifieds/domain/types';

export const classifiedConditionLabels: Record<ClassifiedCondition, string> = {
  new: 'Novo',
  like_new: 'Seminovo',
  used: 'Usado',
  for_parts: 'Para peças',
};

export function formatClassifiedPrice(amountInCents: number | null) {
  if (amountInCents === null) return 'Preço a combinar';

  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(amountInCents / 100);
}

export function formatClassifiedLocation({
  neighborhood,
  cityName,
  stateCode,
}: {
  neighborhood?: string | null;
  cityName: string;
  stateCode: string;
}) {
  const city = stateCode ? `${cityName} - ${stateCode}` : cityName;
  return [neighborhood, city].filter(Boolean).join(' · ');
}

