  .desktopTopbar {
    position: sticky;
    top: 0;
    z-index: 35;
    min-height: 74px;
    display: grid;
    grid-template-columns: minmax(175px, .72fr) minmax(310px, 1.35fr) auto;
    align-items: center;
    gap: 18px;
    padding: 0 24px;
    border-bottom: 1px solid rgba(230, 236, 234, .9);
    background: rgba(255, 255, 255, .94);
    backdrop-filter: blur(18px);
  }

  .topbarTerritory {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 9px;
  }

  .locationDot {
    width: 9px;
    height: 9px;
    flex: 0 0 auto;
    border-radius: 50%;
    background: var(--brand);
    box-shadow: 0 0 0 5px rgba(12, 148, 112, .10);
  }

  .topbarTerritory > span:last-child {
    min-width: 0;
    display: grid;
    gap: 1px;
  }

  .topbarTerritory small {
    color: var(--muted);
    font-size: .58rem;
  }

  .topbarTerritory strong {
    overflow: hidden;
    font-size: .73rem;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .searchCommand {
    min-width: 0;
    min-height: 44px;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    padding: 0 13px;
    border: 1px solid #dce7e3;
    border-radius: 14px;
    background: #f7faf9;
    color: #627082;
    transition:
      border-color .16s ease,
      background-color .16s ease,
      box-shadow .16s ease;
  }

  .searchCommand:hover {
    border-color: #b8d8cc;
    background: #ffffff;
    box-shadow: 0 8px 22px rgba(11, 72, 57, .05);
  }

  .searchText {
    min-width: 0;
    display: grid;
    gap: 1px;
  }

  .searchText strong {
    overflow: hidden;
    color: #334456;
    font-size: .76rem;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .searchText small {
    overflow: hidden;
    color: #89948f;
    font-size: .59rem;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .searchArrow {
    color: var(--brand);
    font-size: .9rem;
    font-weight: 900;
  }

  .accountButton {
    min-height: 44px;
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 0 11px;
    border: 1px solid var(--line);
    border-radius: 13px;
    background: #ffffff;
    font-size: .7rem;
    font-weight: 850;
  }
}

@media (min-width: 1280px) {
  .shell.hasRail {
    grid-template-columns: 236px minmax(0, 1fr) 286px;
  }

  .contextRail {
    position: sticky;
    top: 0;
    height: 100svh;
    display: block;
    overflow-y: auto;
    padding: 90px 16px 28px;
    border-left: 1px solid #dfe9e5;
    background:
      linear-gradient(180deg, #f7faf9 0%, #f1f7f4 100%);
    scrollbar-gutter: stable;
  }

  .hasRail .desktopTopbar {
    padding-left: 26px;
    padding-right: 26px;
  }
}

@media (min-width: 1500px) {
  .shell.hasRail {
    grid-template-columns: 246px minmax(0, 1fr) 310px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sidebarNav a,
  .sidebarUtility a {
    transition: none;
  }
}


@media (min-width: 640px) and (max-width: 979px) {
  .mobileTerritory {
    display: flex;
  }
}

@media (max-width: 639px) {
  .mobileHeader {
    grid-template-columns: auto 1fr auto;
  }
}

